// Median-of-21 streaming filter, TRANSPOSED window: one register per stage
// (regardless of the order in the array) + 2 comparators: median is the
// "correct" one. Same result as the reference, TRANSPOSED window.
module med21 (
  input clk, input rst_n, input [7:0] x, output reg [15:0] y
);
  reg [7:0] w0, w1, w2, w3, w4, w5, w6, w7, w8, w9, w10, w11, w12, w13, w14, w15, w16, w17, w18, w19, w20;
  reg [7:0] t0, t1, t2, t3, t4, t5, t6, t7, t8, t9, t10, t11, t12, t13, t14, t15, t16, t17, t18, t19, t20;
  always @(posedge clk) begin
    if (!rst_n) begin
      y<=0; w0<=0; w1<=0; w2<=0; w3<=0; w4<=0; w5<=0; w6<=0; w7<=0; w8<=0; w9<=0; w10<=0; w11<=0; w12<=0; w13<=0; w14<=0; w15<=0; w16<=0; w17<=0; w18<=0; w19<=0; w20<=0;
    end else begin
      y <= (w0<=x) + (w1<=x) + (w2<=x) + (w3<=x) + (w4<=x) + (w5<=x) + (w6<=x) + (w7<=x) + (w8<=x) + (w9<=x) + (w10<=x) + (w11<=x) + (w12<=x) + (w13<=x) + (w14<=x) + (w15<=x) + (w16<=x) + (w17<=x) + (w18<=x) + (w19<=x) + (w20<=x);
      w20<=w19; w19<=w18; w18<=w17; w17<=w16; w16<=w15; w15<=w14; w14<=w13; w13<=w12; w12<=w11; w11<=w10; w10<=w9; w9<=w8; w8<=w7; w7<=w6; w6<=w5; w5<=w4; w4<=w3; w3<=w2; w2<=w1; w1<=w0; w0 <= x;
    end
  end
endmodule
